class Main {
    // 클래스에 하나인 칸이에요.
    static int count;
    static void setCount(int count) {
        // 매개변수와 필드 이름을 구분해요.
        count = count;
    }

    public static void main(String[] args) {
        // 이번 실험의 시작값이에요.
        int n = 3;
        Main.count = n;
        // 메서드가 받은 값으로 클래스 칸을 바꿔요.
        setCount(n + 4);
        System.out.println(Main.count);
    }
}
